    public static function doUpdate($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(EmailProviderConfigPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        $selectCriteria = new Criteria(EmailProviderConfigPeer::DATABASE_NAME);

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity

            $comparison = $criteria->getComparison(EmailProviderConfigPeer::EMAILPROVIDERCONFIG_ID);
            $value = $criteria->remove(EmailProviderConfigPeer::EMAILPROVIDERCONFIG_ID);
            if ($value) {
                $selectCriteria->add(EmailProviderConfigPeer::EMAILPROVIDERCONFIG_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(EmailProviderConfigPeer::TABLE_NAME);
            }

        } else { // $values is EmailProviderConfig object
            $criteria = $values->buildCriteria(); // gets full criteria
            $selectCriteria = $values->buildPkeyCriteria(); // gets criteria w/ primary key(s)
        }

        // set the correct dbName
        $criteria->setDbName(EmailProviderConfigPeer::DATABASE_NAME);

        return BasePeer::doUpdate($selectCriteria, $criteria, $con);
    }

    /**
     * Deletes all rows from the EMAIL_PROVIDER_CONFIG table.
     *
     * @param      PropelPDO $con the connection to use
     * @return int             The number of affected rows (if supported by underlying database driver).
     * @throws PropelException
