     *
     * @param int $pk the primary key.
     * @param      PropelPDO $con the connection to use
     * @return EmailProviderConfig
     */
    public static function retrieveByPK($pk, PropelPDO $con = null)
    {

        if (null !== ($obj = EmailProviderConfigPeer::getInstanceFromPool((string) $pk))) {
            return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(EmailProviderConfigPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria = new Criteria(EmailProviderConfigPeer::DATABASE_NAME);
        $criteria->add(EmailProviderConfigPeer::EMAILPROVIDERCONFIG_ID, $pk);

        $v = EmailProviderConfigPeer::doSelect($criteria, $con);

        return !empty($v) > 0 ? $v[0] : null;
    }

